idna.core.uts46_remap:
def uts46_remap(domain: str, std3_rules: bool = True, transitional: bool = False) -> str:
    """Re-map the characters in the string according to UTS46 processing."""
    from .uts46data import uts46data
    output = ''
    for (pos, char) in enumerate(domain):
        code_point = ord(char)
        try:
            uts46row = uts46data[(code_point if code_point < 256 else bisect.bisect_left(uts46data, (code_point, 'Z')) - 1)]
            status = uts46row[1]
            replacement = None
            if len(uts46row) == 3:
                replacement = uts46row[2]
            if (status == 'V' or (status == 'D' and not transitional) or (status == '3' and not std3_rules and replacement is None)):
                output += char
            elif (replacement is not None and ((status == 'M' or (status == '3' and not std3_rules) or (status == 'D' and transitional)))):
                output += replacement
            elif status != 'I':
                raise IndexError()
        except IndexError:
            raise InvalidCodepoint('Codepoint {} not allowed at position {} in {}'.format(_unot(code_point), pos + 1, repr(domain)))
    return unicodedata.normalize('NFC', output)

idna.core.ulabel:
def ulabel(label: Union[(str, bytes, bytearray)]) -> str:
    if not isinstance(label, (bytes, bytearray)):
        try:
            label_bytes = label.encode('ascii')
        except UnicodeEncodeError:
            check_label(label)
            return label
    else:
        label_bytes = label
    label_bytes = label_bytes.lower()
    if label_bytes.startswith(_alabel_prefix):
        label_bytes = label_bytes[len(_alabel_prefix):]
        if not label_bytes:
            raise IDNAError('Malformed A-label, no Punycode eligible content found')
        if label_bytes.decode('ascii')[-1] == '-':
            raise IDNAError('A-label must not end with a hyphen')
    else:
        check_label(label_bytes)
        return label_bytes.decode('ascii')
    try:
        label = label_bytes.decode('punycode')
    except UnicodeError:
        raise IDNAError('Invalid A-label')
    check_label(label)
    return label

idna.core.valid_string_length:
def valid_string_length(label: Union[(bytes, str)], trailing_dot: bool) -> bool:
    if len(label) > ((254 if trailing_dot else 253)):
        return False
    return True

idna.core.decode:
def decode(s: Union[(str, bytes, bytearray)], strict: bool = False, uts46: bool = False, std3_rules: bool = False) -> str:
    try:
        if isinstance(s, (bytes, bytearray)):
            s = s.decode('ascii')
    except UnicodeDecodeError:
        raise IDNAError('Invalid ASCII in A-label')
    if uts46:
        s = uts46_remap(s, std3_rules, False)
    trailing_dot = False
    result = []
    if not strict:
        labels = _unicode_dots_re.split(s)
    else:
        labels = s.split('.')
    if (not labels or labels == ['']):
        raise IDNAError('Empty domain')
    if not labels[-1]:
        del labels[-1]
        trailing_dot = True
    for label in labels:
        s = ulabel(label)
        if s:
            result.append(s)
        else:
            raise IDNAError('Empty label')
    if trailing_dot:
        result.append('')
    return '.'.join(result)

idna.core.encode:
def encode(s: Union[(str, bytes, bytearray)], strict: bool = False, uts46: bool = False, std3_rules: bool = False, transitional: bool = False) -> bytes:
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode('ascii')
        except UnicodeDecodeError:
            raise IDNAError('should pass a unicode string to the function rather than a byte string.')
    if uts46:
        s = uts46_remap(s, std3_rules, transitional)
    trailing_dot = False
    result = []
    if strict:
        labels = s.split('.')
    else:
        labels = _unicode_dots_re.split(s)
    if (not labels or labels == ['']):
        raise IDNAError('Empty domain')
    if labels[-1] == '':
        del labels[-1]
        trailing_dot = True
    for label in labels:
        s = alabel(label)
        if s:
            result.append(s)
        else:
            raise IDNAError('Empty label')
    if trailing_dot:
        result.append(b'')
    s = b'.'.join(result)
    if not valid_string_length(s, trailing_dot):
        raise IDNAError('Domain too long')
    return s

requests.utils.set_environ:
@contextlib.contextmanager
def set_environ(env_name, value):
    """Set the environment variable 'env_name' to 'value'

    Save previous value, yield, and then restore the previous value stored in
    the environment variable 'env_name'.

    If 'value' is None, do nothing"""
    value_changed = value is not None
    if value_changed:
        old_value = os.environ.get(env_name)
        os.environ[env_name] = value
    try:
        yield
    finally:
        if value_changed:
            if old_value is None:
                del os.environ[env_name]
            else:
                os.environ[env_name] = old_value

requests.utils.is_ipv4_address:
def is_ipv4_address(string_ip):
    """
    :rtype: bool
    """
    try:
        socket.inet_aton(string_ip)
    except OSError:
        return False
    return True

requests.utils.is_valid_cidr:
def is_valid_cidr(string_network):
    """
    Very simple check of the cidr format in no_proxy variable.

    :rtype: bool
    """
    if string_network.count('/') == 1:
        try:
            mask = int(string_network.split('/')[1])
        except ValueError:
            return False
        if (mask < 1 or mask > 32):
            return False
        try:
            socket.inet_aton(string_network.split('/')[0])
        except OSError:
            return False
    else:
        return False
    return True

requests.utils.should_bypass_proxies:
def should_bypass_proxies(url, no_proxy):
    """
    Returns whether we should bypass proxies or not.

    :rtype: bool
    """

    def get_proxy(key):
        return (os.environ.get(key) or os.environ.get(key.upper()))
    no_proxy_arg = no_proxy
    if no_proxy is None:
        no_proxy = get_proxy('no_proxy')
    parsed = urlparse(url)
    if parsed.hostname is None:
        return True
    if no_proxy:
        no_proxy = (host for host in no_proxy.replace(' ', '').split(',') if host)
        if is_ipv4_address(parsed.hostname):
            for proxy_ip in no_proxy:
                if is_valid_cidr(proxy_ip):
                    if address_in_network(parsed.hostname, proxy_ip):
                        return True
                elif parsed.hostname == proxy_ip:
                    return True
        else:
            host_with_port = parsed.hostname
            if parsed.port:
                host_with_port += f':{parsed.port}'
            for host in no_proxy:
                if (parsed.hostname.endswith(host) or host_with_port.endswith(host)):
                    return True
    with set_environ('no_proxy', no_proxy_arg):
        try:
            bypass = proxy_bypass(parsed.hostname)
        except (TypeError, socket.gaierror):
            bypass = False
    if bypass:
        return True
    return False

urllib3.util.wait._have_working_poll:
def _have_working_poll():
    try:
        poll_obj = select.poll()
        _retry_on_intr(poll_obj.poll, 0)
    except (AttributeError, OSError):
        return False
    else:
        return True

urllib3.util.wait.select_wait_for_socket:
def select_wait_for_socket(sock, read=False, write=False, timeout=None):
    if (not read and not write):
        raise RuntimeError('must specify at least one of read=True, write=True')
    rcheck = []
    wcheck = []
    if read:
        rcheck.append(sock)
    if write:
        wcheck.append(sock)
    fn = partial(select.select, rcheck, wcheck, wcheck)
    (rready, wready, xready) = _retry_on_intr(fn, timeout)
    return bool((rready or wready or xready))

urllib3.util.wait.poll_wait_for_socket:
def poll_wait_for_socket(sock, read=False, write=False, timeout=None):
    if (not read and not write):
        raise RuntimeError('must specify at least one of read=True, write=True')
    mask = 0
    if read:
        mask |= select.POLLIN
    if write:
        mask |= select.POLLOUT
    poll_obj = select.poll()
    poll_obj.register(sock, mask)

    def do_poll(t):
        if t is not None:
            t *= 1000
        return poll_obj.poll(t)
    return bool(_retry_on_intr(do_poll, timeout))

urllib3.util.wait.wait_for_socket:
def wait_for_socket(*args, **kwargs):
    global wait_for_socket
    if _have_working_poll():
        wait_for_socket = poll_wait_for_socket
    elif hasattr(select, 'select'):
        wait_for_socket = select_wait_for_socket
    else:
        wait_for_socket = null_wait_for_socket
    return wait_for_socket(*args, **kwargs)

urllib3.util.wait._retry_on_intr:
def _retry_on_intr(fn, timeout):
    if timeout is None:
        deadline = float('inf')
    else:
        deadline = monotonic() + timeout
    while True:
        try:
            return fn(timeout)
        except (OSError, select.error) as e:
            if e.args[0] != errno.EINTR:
                raise
            else:
                timeout = deadline - monotonic()
                if timeout < 0:
                    timeout = 0
                if timeout == float('inf'):
                    timeout = None
                continue
